	@Test
	void havingQueryPreparationsShareAllLearningKeys(@TempDir Path directory) {
		withStore(directory, false, (store, connection) -> {
			Keys first = keys(explain(connection, parse(HAVING)));
			drain(connection, HAVING);
			Keys second = keys(explain(connection, parse(HAVING)));
			report("having", first, second);
			assertFalse(first.anonymousNames().isEmpty(), "COVERAGE_PREREQUISITE: the parser named the aggregate");
			assertNotEquals(first.anonymousNames(), second.anonymousNames(),
					"COVERAGE_PREREQUISITE: the two parses generated different HAVING names");
			assertFalse(first.event().isEmpty(), "COVERAGE_PREREQUISITE: the HAVING plan carries event identities");
			assertEquals(first.logical(), second.logical(), "logical keys are alpha-normalized and parse-stable");
			assertEquals(first.physical(), second.physical(),
					"two preparations of one HAVING query must produce equal physical residual keys");
			assertEquals(first.event(), second.event(),
					"two preparations of one HAVING query must produce equal physical event keys");
		});
	}

