	@Test
	void internalVariableIdentityRemainsInjective(@TempDir Path directory) {
		withStore(directory, false, (store, connection) -> {
			String template = "SELECT ?s ?x WHERE { ?s <" + P + "> ?i . ?j <" + Q + "> ?x . ?s <" + P + "> ?k"
					+ KEEP_FILTER;
			// A: the Q pattern reads the internal name the first P pattern writes. B: it reads the third one's.
			Keys left = keys(explain(connection, parse(template, Map.of("i", "_anon_inj_1", "j", "_anon_inj_1",
					"k", "_anon_inj_2"))));
			Keys right = keys(explain(connection, parse(template, Map.of("i", "_anon_inj_3", "j", "_anon_inj_4",
					"k", "_anon_inj_4"))));
			report("injective", left, right);
			List<String> leftLayouts = layoutsByLogicalKey(left);
			List<String> rightLayouts = layoutsByLogicalKey(right);
			assertFalse(leftLayouts.isEmpty(), "COVERAGE_PREREQUISITE: the plan carries physical keys");
			assertNotEquals(leftLayouts, rightLayouts,
					"a relation that outputs a different internal variable must have a different layout field");
			assertFalse(left.event().isEmpty(), "COVERAGE_PREREQUISITE: the plan carries event identities");
			assertTrue(disjoint(left.event(), right.event()),
					"different internal variable wiring must produce different event keys");

			String literal = "SELECT ?s WHERE { ?s <" + P + "> ?o . ?o <" + Q + "> ?x" + KEEP_FILTER;
			Keys canonical = keys(explain(connection, parse(literal, Map.of("x", "_anon_literal_1"))));
			Keys named = keys(explain(connection, parse(literal, Map.of())));
			Keys userNamed = keys(explain(connection, renamedUser(literal, "x", "anonymous-name")));
			report("user-anonymous-name", canonical, userNamed);
			assertFalse(named.physical().isEmpty(), "COVERAGE_PREREQUISITE: the plan carries physical keys");
			assertNotEquals(layoutsByLogicalKey(canonical), layoutsByLogicalKey(userNamed),
					"a user variable literally named anonymous-name must not collide with a canonical layout");
			assertTrue(disjoint(canonical.event(), userNamed.event()),
					"a user variable literally named anonymous-name must not collide with a canonical event key");
		});
	}

	@Test
	void parserNamesDoNotDecideTheJoinBasisTieOrder(@TempDir Path directory) {
		withStore(directory, false, (store, connection) -> {
			// Equal-topology factors joined through internal names: the raw names sort one way, then the other.
			// Alpha-equivalent renamings whose encoded names sort in opposite orders (x1 < y1).
			Keys ascending = keys(
					explain(connection, parse(CHAIN, Map.of("a", "_anon_path_x1", "b", "_anon_path_y1"))));
			Keys descending = keys(
					explain(connection, parse(CHAIN, Map.of("a", "_anon_path_y1", "b", "_anon_path_x1"))));
			report("join-basis", ascending, descending);
			assertFalse(ascending.logical().isEmpty(), "COVERAGE_PREREQUISITE: the plan carries logical keys");
			assertEquals(ascending.logical(), descending.logical(),
					"the logical join identity must not depend on how parser names happen to sort");
			assertEquals(ascending.physical(), descending.physical());
			assertEquals(ascending.event(), descending.event());
		});
	}

	/** Inside one factor, bindings with equal roles must not be ordered by how parser names happen to sort. */
	@Test
	void parserNamesDoNotDecideTheBindingOrderInsideAFactor(@TempDir Path directory) {
		withStore(directory, false, (store, connection) -> {
			// Both name orders, constructed rather than left to the parser's counter: x1 < y1 raw and encoded.
			Keys ascending = keys(explain(connection, internal(parse(PATH_ALTERNATIVE), "_anon_path_x1",
					"_anon_path_y1")));
			Keys descending = keys(explain(connection, internal(parse(PATH_ALTERNATIVE), "_anon_path_y1",
					"_anon_path_x1")));
			report("alternative-in-sequence", ascending, descending);
			assertFalse(ascending.logical().isEmpty(), "COVERAGE_PREREQUISITE: the plan carries logical keys");
			assertEquals(ascending.logical(), descending.logical(),
					"the order of equal-role bindings must not depend on how parser names happen to sort");
			assertEquals(ascending.physical(), descending.physical());

			Keys unionAscending = keys(
					explain(connection, parse(SYMMETRIC_UNION, Map.of("a", "_anon_path_x1", "b", "_anon_path_y1"))));
			Keys unionDescending = keys(
					explain(connection, parse(SYMMETRIC_UNION, Map.of("a", "_anon_path_y1", "b", "_anon_path_x1"))));
			report("symmetric-union", unionAscending, unionDescending);
			assertEquals(unionAscending.logical(), unionDescending.logical(),
					"a symmetric factor's binding order must not depend on how parser names happen to sort");
			assertEquals(unionAscending.physical(), unionDescending.physical());
		});
	}

