	/** The query's one parser-generated name spelled differently each time: every learning identity stays equal. */
	private static void assertSameKeysForEveryProbe(Path directory, String label, String query) {
		withStore(directory, false, (store, connection) -> {
			Keys reference = null;
			for (String probe : HASH_ORDER_PROBES) {
				Keys current = keys(explain(connection, internal(parse(query), probe)));
				if (reference == null) {
					assertFalse(current.logical().isEmpty(), "COVERAGE_PREREQUISITE: the plan carries logical keys");
					reference = current;
					continue;
				}
				report(label + "-" + probe, reference, current);
				assertEquals(reference.logical(), current.logical(),
						"logical keys of " + label + " must not depend on the spelling " + probe);
				assertEquals(reference.physical(), current.physical(),
						"physical keys of " + label + " must not depend on the spelling " + probe);
				assertEquals(reference.event(), current.event(),
						"event keys of " + label + " must not depend on the spelling " + probe);
			}
		});
	}

	@Test
	void learningAccumulatesAcrossPreparations(@TempDir Path directory) {
		withStore(directory, false, (store, connection) -> {
			LmdbOperatorFeedbackStats feedback = feedback(store);
			Keys executed = keys(explainExecuted(connection, parse(HAVING)));
			Map<String, Long> executedCounts = observationCounts(feedback, executed);
			Keys executedAgain = keys(explainExecuted(connection, parse(HAVING)));
			Map<String, Long> againCounts = observationCounts(feedback, executedAgain);
			Keys planned = keys(explain(connection, parse(HAVING)));
			Map<String, Long> plannedCounts = observationCounts(feedback, planned);
			report("accumulate", executed, planned);
			System.out.println("KEYSTAB accumulate executed=" + executedCounts + " again=" + againCounts
					+ " planned=" + plannedCounts + " inventory=" + feedback.physicalInventory());
			long learned = executedCounts.values().stream().mapToLong(Long::longValue).sum();
			assertTrue(learned > 0L, "COVERAGE_PREREQUISITE: a completed execution writes a physical cell");
			assertTrue(sum(againCounts) > learned,
					"a second completed preparation must add to the cells the first preparation wrote");
			assertEquals(againCounts, plannedCounts,
					"a later preparation must resolve the cells the earlier preparations wrote");
		});
	}

	@Test
	void identitiesWithoutInternalNamesStayByteIdentical(@TempDir Path directory) {
		withStore(directory, false, (store, connection) -> {
			Keys keys = keys(explain(connection, parse(PLAIN)));
			assertTrue(keys.anonymousNames().isEmpty(), "COVERAGE_PREREQUISITE: no internal variable names");
			assertFalse(keys.physical().isEmpty() || keys.event().isEmpty(),
					"COVERAGE_PREREQUISITE: the plan carries physical and event identities");
			String logical = digest(keys.logicalBytes());
			String physical = digest(keys.physicalBytes());
			String event = digest(keys.eventBytes());
			System.out.println("KEYSTAB golden logical=" + logical + " physical=" + physical + " event=" + event);
			keys.logical().forEach(line -> System.out.println("KEYSTAB golden-logical " + line));
			keys.physicalBytes().forEach(bytes -> System.out.println("KEYSTAB golden-physical " + bytes));
			keys.eventBytes().forEach(bytes -> System.out.println("KEYSTAB golden-event " + bytes));
			assertEquals(PLAIN_LOGICAL_GOLDEN, logical, "persisted logical identities are byte-identical");
			assertEquals(PLAIN_PHYSICAL_GOLDEN, physical, "persisted physical residual keys are byte-identical");
			assertEquals(PLAIN_EVENT_GOLDEN, event, "persisted physical event keys are byte-identical");
		});
	}

